<script setup lang="ts">
// @ts-nocheck
import{onMounted,ref}from'vue';import{api}from'../api';const credentials=ref<any[]>([]),connections=ref<any[]>([]),error=ref(''),cred=ref({name:'',private_key:'',passphrase:''}),conn=ref({name:'',host:'',port:22,username:'',credential_id:0,timeout_seconds:10});async function load(){[credentials.value,connections.value]=await Promise.all([api('/api/ssh-credentials'),api('/api/ssh-connections')])}async function addCredential(){try{await api('/api/ssh-credentials',{method:'POST',body:JSON.stringify(cred.value)});cred.value={name:'',private_key:'',passphrase:''};await load()}catch(e){error.value=(e as Error).message}}async function addConnection(){try{await api('/api/ssh-connections',{method:'POST',body:JSON.stringify(conn.value)});await load()}catch(e){error.value=(e as Error).message}}async function test(id:number){try{await api(`/api/ssh-connections/${id}/test`,{method:'POST'});alert('连接成功（未校验主机密钥）')}catch(e){alert((e as Error).message)}}onMounted(load)
</script>
<template><div class="page-title"><div><router-link to="/">← 项目</router-link><h1>SSH 资源</h1><p class="error">警告：当前版本不校验服务器主机密钥。</p></div></div><p v-if="error" class="error">{{error}}</p><div class="two-col"><section class="card"><h2>共享私钥</h2><form @submit.prevent="addCredential"><label>名称<input v-model="cred.name" required></label><label>私钥<textarea v-model="cred.private_key" required rows="8"></textarea></label><label>口令（可选）<input v-model="cred.passphrase" type="password"></label><button>添加密钥</button></form><table><tr v-for="x in credentials" :key="x.id"><td>{{x.name}}</td><td><code>{{x.fingerprint}}</code></td></tr></table></section><section class="card"><h2>服务器连接</h2><form @submit.prevent="addConnection"><label>名称<input v-model="conn.name" required></label><label>主机<input v-model="conn.host" required></label><label>端口<input v-model.number="conn.port" type="number"></label><label>用户名<input v-model="conn.username" required></label><label>凭据<select v-model.number="conn.credential_id"><option v-for="x in credentials" :value="x.id">{{x.name}}</option></select></label><button>添加服务器</button></form><table><tr v-for="x in connections" :key="x.id"><td>{{x.name}}</td><td>{{x.username}}@{{x.host}}:{{x.port}}</td><td><button class="link" @click="test(x.id)">测试</button></td></tr></table></section></div></template>
